N=22
bg=5
out=[[bg]*N for _ in range(N)]
# final frame coordinates: (top, left, border, interior)
frames=[(0,12,2,1),(2,0,8,4),(2,17,2,3),(8,0,8,3),(8,17,2,9),(14,0,8,7),(14,17,2,7),(16,5,8,9)]
for y,x,b,i in frames:
    for r in range(5):
        for c in range(5):
            out[y+r][x+c]=i if 1<=r<=3 and 1<=c<=3 else b
print('\n'.join(' '.join(map(str,row)) for row in out))
